// Compile-Time Polymorphism: Templates/Overloading

template <typename T>
T process_data(T data) {
    // T determined statically (at compilation)
    return data * 2;
}

int result_i = process_data(10);    // process_data<int>
double result_d = process_data(5.5);// process_data<double>


// Run-Time Polymorphism: Virtual Functions

class Shape {
public:
    virtual double area() const = 0; // Runtime resolution
    virtual ~Shape() = default;
};

class Circle : public Shape {
    double r;
public:
    explicit Circle(double radius) : r(radius) {}
    double area() const override { return 3.14 * r * r; }
};

